import React, { useEffect, useState } from "react";
import { Container, Card } from "react-bootstrap";

function Maps() {
  const [markers, setMarkers] = useState([]);

  // ดึงพิกัดจาก Database
  useEffect(() => {
    fetch("http://localhost:3000/api/map-data")
      .then((res) => res.json())
      .then((data) => {
        console.log("Map Data:", data);
        setMarkers(data);
      })
      .catch((err) => console.error(err));
  }, []);

  return (
    <Container fluid>
      <Card>
        <Card.Header>
          <Card.Title as="h4">📍 Bus Stop Locations</Card.Title>
          <p className="card-category">
            แสดงตำแหน่งป้ายรถจากฐานข้อมูล
          </p>
        </Card.Header>

        <Card.Body>
          {/* 🗺 แผนที่ (ไม่ต้องลง library) */}
          <div style={{ height: "400px", marginBottom: "20px" }}>
            <iframe
              title="OpenStreetMap"
              width="100%"
              height="100%"
              frameBorder="0"
              scrolling="no"
              src="https://www.openstreetmap.org/export/embed.html?bbox=100.45,13.70,100.60,13.80&layer=mapnik"
              style={{ borderRadius: "10px" }}
            />
          </div>

          {/* 📋 รายการพิกัดจาก DB */}
          <h5>📌 Bus Stop Data (from Database)</h5>
          <ul>
            {markers.map((stop, index) => (
              <li key={index} style={{ marginBottom: "10px" }}>
                <strong>{stop.Name}</strong>
                <br />
                Lat: {stop.latitude}, Lng: {stop.longitude}
              </li>
            ))}
          </ul>

          <p style={{ color: "green" }}>
            ✔ แผนที่ใช้ OpenStreetMap (ไม่ต้องใช้ Google API / ไม่ต้องติดตั้ง leaflet)
          </p>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default Maps;
